export function microphoneHelp({userAgent='',standalone=false}={}){if(/iPhone|iPad|iPod/.test(userAgent))return 'iPhone: Ayarlar → Uygulamalar → Safari → Mikrofon. Siteyi Safari’de de açıp izni kontrol et. İznin kalıcı tutulmasına iOS karar verir.';return 'Chrome: adres çubuğundaki site ayarları → İzinler → Mikrofon → İzin ver. İzin sorulduğunda tek seferlik seçenek yerine sürekli izin seçeneği varsa onu seç. Telefon ayarlarında Chrome’un mikrofon izni de açık olmalı.';}
export function setupMicrophone({navigator:nav=globalThis.navigator,onChange=()=>{}}={}){let current='unknown',permission;const report=()=>onChange(current);async function refresh(){try{permission=await nav.permissions?.query({name:'microphone'});current=permission?.state||'unknown';if(permission)permission.onchange=()=>{current=permission.state;report();};}catch{current='unknown';}report();return current;}
async function authorize(){if(!nav.mediaDevices?.getUserMedia)throw Error('Bu tarayıcı mikrofon izin ayarını desteklemiyor. Telefon klavyendeki mikrofonu kullanabilirsin.');try{const stream=await nav.mediaDevices.getUserMedia({audio:true});for(const track of stream.getTracks())track.stop();await refresh();return current;}catch(error){await refresh();throw error;}}
return {refresh,authorize,state:()=>current};}
